{
  "requirement_id": "REQ-007",
  "cases": [
    {
      "id": "TC-1",
      "title": "Project member can successfully read project, task list, and task detail",
      "surface": "api",
      "steps": [
        "POST /api/projects with header X-User: alice to create a project",
        "POST /api/projects/{pid}/tasks with header X-User: alice to create a task",
        "GET /api/projects/{pid} with header X-User: alice",
        "GET /api/projects/{pid}/tasks with header X-User: alice",
        "GET /api/tasks/{tid} with header X-User: alice"
      ],
      "expected": "專案成員可以成功讀取專案、任務列表與任務詳情（GET /api/tasks/{tid}）"
    },
    {
      "id": "TC-2",
      "title": "Non-project member receives 403 error when trying to read task detail",
      "surface": "api",
      "steps": [
        "POST /api/projects with header X-User: alice to create a project",
        "POST /api/projects/{pid}/tasks with header X-User: alice to create a task",
        "GET /api/tasks/{tid} with header X-User: bob"
      ],
      "expected": "非專案成員嘗試讀取時，系統應回傳 403 錯誤"
    },
    {
      "id": "TC-3",
      "title": "System returns 404 error when requested task resource does not exist",
      "surface": "api",
      "steps": [
        "GET /api/tasks/999999 with header X-User: alice"
      ],
      "expected": "當請求的資源不存在時，系統應回傳 404 錯誤"
    }
  ]
}

